import { test, expect } from '@playwright/test';

test.describe('Form Validation - Required Fields Highlighting', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/form');
  });

  test('should highlight required fields when submitting an empty form', async ({ page }) => {
    // Verify form is visible
    const form = page.getByRole('form');
    await expect(form).toBeVisible();

    // Verify required fields have validation attribute
    const nameInput = page.getByLabel('Full Name');
    const emailInput = page.getByLabel('Email Address');
    const phoneInput = page.getByLabel('Phone Number');
    const submitButton = page.getByRole('button', { name: 'Submit' });

    await expect(nameInput).toBeVisible();
    await expect(emailInput).toBeVisible();
    await expect(phoneInput).toBeVisible();
    await expect(submitButton).toBeVisible();

    // Submit empty form
    await submitButton.click();

    // Verify error messages appear for all required fields
    const nameError = page.getByText('Full Name is required');
    const emailError = page.getByText('Email Address is required');
    const phoneError = page.getByText('Phone Number is required');
    await expect(nameError).toBeVisible();
    await expect(emailError).toBeVisible();
    await expect(phoneError).toBeVisible();

    // Verify required fields are highlighted with error styling
    await expect(nameInput).toHaveClass(/error-highlight/);
    await expect(emailInput).toHaveClass(/error-highlight/);
    await expect(phoneInput).toHaveClass(/error-highlight/);

    // Verify form submission was prevented
    await expect(page).not.toContainText('Form submitted successfully');
  });

  test('should clear error highlights when required fields are filled', async ({ page }) => {
    // Verify form is visible
    const form = page.getByRole('form');
    await expect(form).toBeVisible();

    // Fill in all required fields
    const nameInput = page.getByLabel('Full Name');
    const emailInput = page.getByLabel('Email Address');
    const phoneInput = page.getByLabel('Phone Number');
    const submitButton = page.getByRole('button', { name: 'Submit' });

    await nameInput.fill('John Doe');
    await emailInput.fill('john@example.com');
    await phoneInput.fill('123-462-101');

    // Verify error messages are not visible
    const nameError = page.getByText('Full Name is required');
    const emailError = page.getByText('Email Address is required');
    const phoneError = page.getByText('Phone Number is required');
    await expect(nameError).not.toBeVisible();
    await expect(emailError).not.toBeVisible();
    await expect(phoneError).not.toBeVisible();

    // Verify required fields are not highlighted
    await expect(nameInput).not.toHaveClass(/error-highlight/);
    await expect(emailInput).not.toHaveClass(/error-highlight/);
    await expect(phoneInput).not.toHaveClass(/error-highlight/);

    // Submit the form with valid data
    await submitButton.click();

    // Verify success message appears
    const successMessage = page.getByText('Form submitted successfully');
    await expect(successMessage).toBeVisible();

    // Verify form is cleared
    await expect(nameInput).toHaveValue('');
    await expect(emailInput).toHaveValue('');
    await expect(phoneInput).toHaveValue('');
  });
});
